package io.metagen.engine.crud;

import io.metagen.core.domain.MetaEntity;
import io.metagen.core.domain.MetaField;
import io.metagen.core.domain.MetaFieldType;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Pure unit tests of the SQL generated by {@link DynamicQueryBuilder} (no Spring, no DB). */
class DynamicQueryBuilderTest {

    private DynamicQueryBuilder builder;
    private MetaEntity entity;

    @BeforeEach
    void setUp() {
        builder = new DynamicQueryBuilder();
        entity = MetaEntity.builder()
            .name("person").label("Person").tableName("data_person")
            .softDelete(true).auditable(true).build();
        entity.getFields().add(field("name", MetaFieldType.STRING, true));
        entity.getFields().add(field("age", MetaFieldType.INTEGER, false));
        entity.getFields().add(field("notes", MetaFieldType.JSON, true));
    }

    private static MetaField field(String name, MetaFieldType type, boolean searchable) {
        return MetaField.builder().name(name).label(name).type(type).searchable(searchable).build();
    }

    @Test
    @DisplayName("select quotes every identifier and always filters deleted rows")
    void select_basics() {
        String sql = builder.buildSelect(entity, List.of(), false, null, "ASC");
        assertThat(sql).contains("FROM \"data_person\"")
            .contains("\"deleted_at\" IS NULL")
            .contains("\"id\"", "\"state\"", "\"name\"", "\"age\"")
            .contains("ORDER BY \"created_at\" ASC")
            .endsWith("LIMIT :pageSize OFFSET :offset");
    }

    @Test
    @DisplayName("where fragments produced by conditions are ANDed in")
    void select_whereFragments() {
        String sql = builder.buildSelect(entity, List.of("(\"age\" > :f_0)"), false, "age", "DESC");
        assertThat(sql).contains("AND (\"age\" > :f_0)").contains("ORDER BY \"age\" DESC");
    }

    @Test
    @DisplayName("search only covers searchable text columns")
    void select_search() {
        String sql = builder.buildSelect(entity, List.of(), true, null, "ASC");
        assertThat(sql).contains("\"name\" ILIKE :search")
            .doesNotContain("\"age\" ILIKE").doesNotContain("\"notes\" ILIKE");
    }

    @Test
    @DisplayName("an unknown or malicious sort field falls back to created_at")
    void select_sortInjection() {
        String sql = builder.buildSelect(entity, List.of(), false, "name; DROP TABLE x --", "ASC");
        assertThat(sql).contains("ORDER BY \"created_at\"").doesNotContain("DROP");
    }

    @Test
    @DisplayName("a sort direction other than ASC is treated as DESC")
    void select_sortDir() {
        assertThat(builder.buildSelect(entity, List.of(), false, null, "x; --")).contains("DESC, \"id\" ASC");
    }

    @Test
    @DisplayName("count shares the WHERE clause with select")
    void count() {
        String sql = builder.buildCount(entity, List.of("(\"age\" > :f_0)"), true);
        assertThat(sql).startsWith("SELECT COUNT(*) FROM \"data_person\"")
            .contains("AND (\"age\" > :f_0)").contains("ILIKE :search");
    }

    @Test
    @DisplayName("selectById keeps the soft-delete filter and extra fragments")
    void selectById() {
        assertThat(builder.buildSelectById(entity, List.of("(\"created_by\" = :f_0)")))
            .contains("\"id\" = :id").contains("\"deleted_at\" IS NULL").contains("AND (\"created_by\" = :f_0)");
    }

    @Test
    @DisplayName("insert uses bind params, casts JSON, and returns the row")
    void insert() {
        String sql = builder.buildInsert(entity, List.of("name", "notes"));
        assertThat(sql).startsWith("INSERT INTO \"data_person\"")
            .contains("\"name\"", ":name", "CAST(:notes AS jsonb)", ":createdBy")
            .contains("RETURNING");
    }

    @Test
    @DisplayName("insert rejects a field that is not declared")
    void insert_unknownField() {
        assertThatThrownBy(() -> builder.buildInsert(entity, List.of("hacker")))
            .isInstanceOf(IllegalArgumentException.class).hasMessageContaining("hacker");
    }

    @Test
    @DisplayName("update sets only the given fields plus audit columns")
    void update() {
        String sql = builder.buildUpdate(entity, List.of("age"));
        assertThat(sql).contains("\"age\" = :age").contains("\"updated_at\" = NOW()")
            .contains("\"updated_by\" = :updatedBy").contains("\"deleted_at\" IS NULL").contains("RETURNING");
    }

    @Test
    @DisplayName("soft delete flags the row instead of removing it")
    void softDelete() {
        assertThat(builder.buildSoftDelete(entity)).startsWith("UPDATE").contains("\"deleted_at\" = NOW()");
        assertThat(builder.buildHardDelete(entity)).startsWith("DELETE FROM \"data_person\"");
    }

    @Test
    @DisplayName("state update is a compare-and-set on the previous state")
    void stateUpdate() {
        assertThat(builder.buildStateUpdate(entity))
            .contains("\"state\" = :newState")
            .contains("\"state\" IS NOT DISTINCT FROM CAST(:expectedState AS VARCHAR)")
            .contains("RETURNING");
    }
}
